North0.CentralBody = Earth;
North0.StateType = Spherical;
North0.HorizonReference = Ellipsoid;
North0.Location1 = 30;
North0.Location2 = 0;
North0.Location3 = 0;
North0.Id = 'North0';
North0.AddHardware = {Transmitter1, Receiver1, Antenna1};
North0.MinimumElevationAngle = 0;
North0.ErrorModels = {RangeModel};
simData.AddTrackingConfig = {{North0, SimSat, North0}, 'Range_Skin'};
